1	/* EatHours: shared opening-hours logic (kitchen and bar), time-aware status lines and the "tonight" board.
2	   Hours shape: { mon: [["11:30","21:00"]], ... } in local 24h time. A close time earlier than its open time means after midnight. */
3	(function () {
4	  const DAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
5	  const LABEL = { sun: 'Sunday', mon: 'Monday', tue: 'Tuesday', wed: 'Wednesday', thu: 'Thursday', fri: 'Friday', sat: 'Saturday' };
6	
7	  const toMin = (t) => { const [h, m] = String(t).split(':').map(Number); return h * 60 + (m || 0); };
8	
9	  function fmt(t) {
10	    const m = typeof t === 'number' ? ((t % 1440) + 1440) % 1440 : toMin(t);
11	    const h = Math.floor(m / 60), mm = m % 60;
12	    const hh = ((h + 11) % 12) + 1;
13	    const ampm = h >= 12 ? 'PM' : 'AM';
14	    return mm ? `${hh}:${String(mm).padStart(2, '0')} ${ampm}` : `${hh} ${ampm}`;
15	  }
16	
17	  function now() {
18	    const d = new Date();
19	    return { day: DAYS[d.getDay()], minutes: d.getHours() * 60 + d.getMinutes(), date: d };
20	  }
21	
22	  // Expands a day's ranges into absolute minute spans relative to that day's midnight (close may exceed 1440).
23	  function spans(hours, day) {
24	    return (hours && hours[day] ? hours[day] : []).map((r) => {
25	      const o = toMin(r[0]); let c = toMin(r[1]);
26	      if (c <= o) c += 1440;
27	      return { open: o, close: c };
28	    });
29	  }
30	
31	  // Status at a given moment for one hours table.
32	  function status(hours, at) {
33	    at = at || now();
34	    const dayIdx = DAYS.indexOf(at.day);
35	    const yesterday = DAYS[(dayIdx + 6) % 7];
36	    // A span from yesterday may still be running past midnight.
37	    for (const s of spans(hours, yesterday)) {
38	      if (s.close > 1440 && at.minutes < s.close - 1440) return { open: true, closes: s.close - 1440, closingSoon: (s.close - 1440 - at.minutes) <= 45 };
39	    }
40	    let next = null;
41	    for (const s of spans(hours, at.day)) {
42	      if (at.minutes >= s.open && at.minutes < s.close) return { open: true, closes: s.close % 1440, closingSoon: (s.close - at.minutes) <= 45 };
43	      if (at.minutes < s.open && (next === null || s.open < next)) next = s.open;
44	    }
45	    if (next !== null) return { open: false, opens: next, today: true };
46	    for (let i = 1; i <= 7; i++) {
47	      const d = DAYS[(dayIdx + i) % 7];
48	      const sp = spans(hours, d);
49	      if (sp.length) return { open: false, opens: sp[0].open, day: d, inDays: i };
50	    }
51	    return { open: false, none: true };
52	  }
53	
54	  // Human line for a restaurant with kitchen hours and optional bar hours.
55	  function statusLine(r, at) {
56	    at = at || now();
57	    const k = status(r.hours, at);
58	    const b = r.bar_hours ? status(r.bar_hours, at) : null;
59	    if (k.open) {
60	      if (b && b.open && b.closes !== k.closes && b.closes > k.closes) return `Kitchen until ${fmt(k.closes)}, bar until ${fmt(b.closes)}`;
61	      return k.closingSoon ? `Closing soon, kitchen until ${fmt(k.closes)}` : `Open until ${fmt(k.closes)}`;
62	    }
63	    if (b && b.open) return `Bar open until ${fmt(b.closes)}, kitchen closed`;
64	    if (k.none) return 'Hours not posted';
65	    if (k.today) return `Opens at ${fmt(k.opens)} today`;
66	    if (k.inDays === 1) return `Opens tomorrow at ${fmt(k.opens)}`;
67	    return `Opens ${LABEL[k.day]} at ${fmt(k.opens)}`;
68	  }
69	
70	  function isOpen(r, at) {
71	    at = at || now();
72	    return status(r.hours, at).open || (r.bar_hours ? status(r.bar_hours, at).open : false);
73	  }
74	
75	  // Latest closing minute today (kitchen or bar), or null if closed today.
76	  function closesTonight(r, day) {
77	    day = day || now().day;
78	    let latest = null;
79	    for (const s of spans(r.hours, day).concat(r.bar_hours ? spans(r.bar_hours, day) : [])) {
80	      if (latest === null || s.close > latest) latest = s.close;
81	    }
82	    return latest;
83	  }
84	
85	  // True when the place is still open at the given hour (24h, e.g. 21 for 9 PM) on the given day.
86	  function openPast(r, hour, day) {
87	    const c = closesTonight(r, day);
88	    return c !== null && c > hour * 60;
89	  }
90	
91	  // Board of tonight's availability for a list of restaurants.
92	  function tonight(list, day) {
93	    day = day || now().day;
94	    return list.map((r) => {
95	      const c = closesTonight(r, day);
96	      const kitchen = spans(r.hours, day);
97	      const bar = r.bar_hours ? spans(r.bar_hours, day) : [];
98	      return {
99	        slug: r.slug, name: r.name, closes: c, closesText: c === null ? 'Closed tonight' : `Until ${fmt(c)}`,
100	        kitchenCloses: kitchen.length ? Math.max.apply(null, kitchen.map((s) => s.close)) : null,
101	        barCloses: bar.length ? Math.max.apply(null, bar.map((s) => s.close)) : null,
102	        past8: c !== null && c > 20 * 60, past9: c !== null && c > 21 * 60, past10: c !== null && c > 22 * 60,
103	      };
104	    });
105	  }
106	
107	  // Daypart of a moment: brunch, lunch, afternoon, dinner, late.
108	  function daypart(at) {
109	    at = at || now();
110	    const h = at.minutes / 60;
111	    if (h < 11) return (at.day === 'sat' || at.day === 'sun') ? 'brunch' : 'morning';
112	    if (h < 14.5) return (at.day === 'sat' || at.day === 'sun') ? 'brunch' : 'lunch';
113	    if (h < 17) return 'afternoon';
114	    if (h < 20) return 'dinner';
115	    if (h < 24) return 'late';
116	    return 'late';
117	  }
118	
119	  window.EatHours = { DAYS, LABEL, toMin, fmt, now, spans, status, statusLine, isOpen, closesTonight, openPast, tonight, daypart };
120	})();
