1:/* Components: nav, search, hero, bento, restaurant stack, map, planner, after dark, forms, footer, drawer. */
160:.map-split { display: grid; grid-template-columns: minmax(300px, 0.8fr) 1.4fr; gap: clamp(1.5rem, 4vw, 4rem); align-items: start; }
161:.map-copy { display: grid; gap: 1.25rem; }
171:.map-toggles { display: flex; gap: 0.4rem; flex-wrap: wrap; }
172:.map-frame { position: sticky; top: calc(var(--nav-h) + 1.5rem); }
173:.map { width: 100%; aspect-ratio: 4 / 3.4; min-height: 420px; border-radius: var(--r-in); overflow: hidden; background: var(--surface-2); }
174:.map-page .map { aspect-ratio: auto; height: calc(100dvh - var(--nav-h) - 3rem); }
175:.leaflet-container { font-family: var(--font-body); background: var(--surface-2); }
176:.leaflet-control-attribution { font-size: 10px !important; background: var(--glass) !important; color: var(--ink-3) !important; }
177:.leaflet-control-attribution a { color: var(--ink-2) !important; }
178:.leaflet-bar { border: 1px solid var(--line) !important; box-shadow: var(--shadow-sm) !important; border-radius: 12px !important; overflow: hidden; }
179:.leaflet-bar a { background: var(--surface) !important; color: var(--ink) !important; border-bottom-color: var(--line) !important; }
180:.eat-pin { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 50%; background: var(--accent); color: var(--accent-ink); font-family: var(--font-display); font-weight: 800; font-size: 1rem; border: 3px solid var(--bg); box-shadow: 0 8px 20px -6px rgba(0,0,0,0.45); transform: translate(0, 0); transition: transform var(--dur-fast) var(--ease-out); }
181:.eat-pin.alt { background: var(--ink); color: var(--bg); width: 30px; height: 30px; font-size: 0.75rem; }
182:.eat-pin.alt svg { width: 14px; height: 14px; }
183:.eat-pin.is-active, .eat-pin:hover { transform: scale(1.18); }
184:.eat-pin-wrap { background: transparent; border: 0; }
185:.leaflet-popup-content-wrapper { border-radius: 14px !important; background: var(--surface) !important; color: var(--ink) !important; box-shadow: var(--shadow) !important; }
186:.leaflet-popup-tip { background: var(--surface) !important; }
187:.leaflet-popup-content { margin: 0.9rem 1rem !important; font-size: 0.9rem; line-height: 1.4; }
188:.leaflet-popup-content strong { font-family: var(--font-display); font-size: 1.05rem; display: block; margin-bottom: 0.2rem; }
189:.leaflet-popup-content a { color: var(--accent); font-weight: 600; }
190:.leaflet-popup-close-button { color: var(--ink-3) !important; }
191:.walk-label { background: var(--surface); color: var(--ink); border: 1px solid var(--line); border-radius: var(--r-pill); padding: 2px 8px; font-size: 11px; font-weight: 700; white-space: nowrap; box-shadow: var(--shadow-sm); }
192:.walk-label-wrap { background: transparent; border: 0; }
193:@media (max-width: 900px) { .map-split { grid-template-columns: 1fr; } .map-frame { position: static; } }

