/* Smoke test for src/js/map.js.
   Loads hours.js and map.js into a vm context with a hand-rolled window/document and a recording Leaflet stub,
   then checks the pure logic: marker counts, the loop polyline, walking labels, popups, layers, theme and focus(). */
import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';

const ROOT = 'C:/Users/Kenneth Rodas/Documents/GitHub/eatdanville';
const HOURS = fs.readFileSync(`${ROOT}/src/js/hours.js`, 'utf8');
const MAP = fs.readFileSync(`${ROOT}/src/js/map.js`, 'utf8');
const RESTAURANTS = JSON.parse(fs.readFileSync(`${ROOT}/data/restaurants.json`, 'utf8'));
const DISTRICT = JSON.parse(fs.readFileSync(`${ROOT}/data/district.json`, 'utf8'));

const CAR_PATH = 'M240,104H229.2L201.42,41.5';
const PIN_PATH = 'M128,64a40,40,0,1,0,40,40A40,40,0,0,0,128,64Z';

let passed = 0;
const failures = [];
function test(name, fn) {
  try { fn(); passed++; console.log(`  ok   ${name}`); }
  catch (err) { failures.push({ name, err }); console.log(`  FAIL ${name}\n       ${err && err.message}`); }
}
function group(name) { console.log(`\n${name}`); }

/* ---------------------------------------------------------------- fake DOM */

function selMatch(node, sel) {
  const attr = sel.match(/^\[data-([a-z-]+)(?:="([^"]*)")?\]$/);
  if (attr) {
    const key = attr[1].replace(/-([a-z])/g, (m, c) => c.toUpperCase());
    if (!node.dataset || !(key in node.dataset)) return false;
    return attr[2] === undefined ? true : node.dataset[key] === attr[2];
  }
  if (sel.startsWith('.')) return node.classList.contains(sel.slice(1));
  return node.tagName === sel;
}

function makeEl(dataset = {}, tag = 'div', classes = []) {
  const listeners = Object.create(null);
  const owned = new Set(classes);
  const node = {
    tagName: tag,
    dataset,
    children: [],
    parent: null,
    attrs: Object.create(null),
    listeners,
    classList: {
      add: (c) => owned.add(c),
      remove: (c) => owned.delete(c),
      contains: (c) => owned.has(c),
      toggle: (c, on) => { const want = on === undefined ? !owned.has(c) : !!on; if (want) owned.add(c); else owned.delete(c); return want; },
    },
    setAttribute(k, v) { node.attrs[k] = String(v); },
    getAttribute(k) { return k in node.attrs ? node.attrs[k] : null; },
    addEventListener(type, fn) { (listeners[type] = listeners[type] || []).push(fn); },
    removeEventListener(type, fn) { listeners[type] = (listeners[type] || []).filter((f) => f !== fn); },
    dispatch(type, ev) { (listeners[type] || []).slice().forEach((fn) => fn(Object.assign({ type, target: node }, ev || {}))); },
    appendChild(child) { child.parent = node; node.children.push(child); return child; },
    contains(other) { let n = other; while (n) { if (n === node) return true; n = n.parent; } return false; },
    querySelector(sel) { return node.descendants().find((c) => selMatch(c, sel)) || null; },
    querySelectorAll(sel) { return node.descendants().filter((c) => selMatch(c, sel)); },
    closest(sel) { let n = node; while (n) { if (selMatch(n, sel)) return n; n = n.parent; } return null; },
    descendants() { return node.children.flatMap((c) => [c, ...c.descendants()]); },
  };
  return node;
}

// Turns a divIcon html string into a tiny element tree so classList and querySelector work on it.
function nodeFromHtml(html) {
  const host = makeEl({}, 'div');
  const re = /<(div|span)\s+class="([^"]*)"/g;
  let m;
  while ((m = re.exec(html))) host.appendChild(makeEl({}, m[1], m[2].split(/\s+/).filter(Boolean)));
  host.html = html;
  return host;
}

function makeDocument() {
  const listeners = Object.create(null);
  const doc = {
    readyState: 'complete',
    documentElement: makeEl({ theme: 'light' }, 'html'),
    activeElement: null,
    all: [],
    listeners,
    querySelectorAll(sel) { return doc.all.filter((n) => selMatch(n, sel)); },
    querySelector(sel) { return doc.querySelectorAll(sel)[0] || null; },
    addEventListener(type, fn) { (listeners[type] = listeners[type] || []).push(fn); },
    removeEventListener(type, fn) { listeners[type] = (listeners[type] || []).filter((f) => f !== fn); },
    dispatch(type, ev) { (listeners[type] || []).slice().forEach((fn) => fn(Object.assign({ type }, ev || {}))); },
  };
  return doc;
}

/* ------------------------------------------------------------ leaflet stub */

function makeL(calls) {
  function makeGroup() {
    const g = {
      kind: 'layerGroup',
      layers: [],
      map: null,
      addLayer(l) { g.layers.push(l); if (g.map && l.setOnMap) l.setOnMap(true); return g; },
      removeLayer(l) { g.layers = g.layers.filter((x) => x !== l); return g; },
      addTo(map) { map.addLayer(g); return g; },
      getLayers() { return g.layers; },
      setOnMap(on) { g.map = on ? g.map : null; g.layers.forEach((l) => l.setOnMap && l.setOnMap(on)); },
    };
    return g;
  }

  function makeMarker(latlng, opts) {
    const icon = (opts && opts.icon) || {};
    const el = nodeFromHtml(icon.html || '');
    const m = {
      kind: 'marker',
      latlng,
      options: opts || {},
      icon,
      popup: null,
      popupOpened: 0,
      onMap: false,
      handlers: Object.create(null),
      addTo(target) { if (target && target.addLayer) target.addLayer(m); return m; },
      setOnMap(on) { m.onMap = !!on; },
      bindPopup(html, o) { m.popup = html; m.popupOptions = o; return m; },
      openPopup() { m.popupOpened++; (m.handlers.popupopen || []).forEach((fn) => fn({ type: 'popupopen' })); return m; },
      closePopup() { (m.handlers.popupclose || []).forEach((fn) => fn({ type: 'popupclose' })); return m; },
      getLatLng() { return latlng; },
      getElement() { return m.onMap ? el : null; },
      on(type, fn) { (m.handlers[type] = m.handlers[type] || []).push(fn); return m; },
    };
    calls.marker.push(m);
    return m;
  }

  return {
    map(el, opts) {
      const handlers = Object.create(null);
      const map = {
        kind: 'map',
        el,
        options: opts,
        layers: [],
        zoom: (opts && opts.zoom) || 17,
        addLayer(l) { if (map.layers.indexOf(l) === -1) map.layers.push(l); l.map = map; if (l.setOnMap) { l.map = map; l.layers && l.layers.forEach((x) => x.setOnMap && x.setOnMap(true)); } return map; },
        removeLayer(l) { map.layers = map.layers.filter((x) => x !== l); if (l.layers) l.layers.forEach((x) => x.setOnMap && x.setOnMap(false)); return map; },
        hasLayer(l) { return map.layers.indexOf(l) !== -1; },
        setView(ll, z) { calls.setView.push({ ll, z }); map.zoom = z; return map; },
        fitBounds(b, o) { calls.fitBounds.push({ b, o }); return map; },
        flyTo(ll, z, o) { calls.flyTo.push({ ll, z, o }); return map; },
        getZoom() { return map.zoom; },
        invalidateSize() { calls.invalidateSize++; return map; },
        on(type, fn) { (handlers[type] = handlers[type] || []).push(fn); return map; },
        off() { return map; },
        emit(type, ev) { (handlers[type] || []).forEach((fn) => fn(ev || {})); },
        scrollWheelZoom: (() => { let on = false; return { enable() { on = true; }, disable() { on = false; }, enabled() { return on; } }; })(),
        dragging: (() => { let on = false; return { enable() { on = true; }, disable() { on = false; }, enabled() { return on; } }; })(),
      };
      calls.map.push(map);
      return map;
    },
    tileLayer(url, opts) {
      const t = { kind: 'tileLayer', url, options: opts, urls: [url], addTo(map) { map.addLayer(t); return t; }, setUrl(u) { t.url = u; t.urls.push(u); return t; } };
      calls.tileLayer.push(t);
      return t;
    },
    layerGroup() { const g = makeGroup(); calls.layerGroup.push(g); return g; },
    marker: makeMarker,
    divIcon(o) { calls.divIcon.push(o); return Object.assign({ kind: 'divIcon' }, o); },
    polyline(pts, opts) {
      const p = { kind: 'polyline', pts, options: opts, styles: [], addTo(t) { t.addLayer(p); return p; }, setStyle(s) { p.styles.push(s); return p; }, setOnMap() {} };
      calls.polyline.push(p);
      return p;
    },
    latLngBounds(pts) { return { kind: 'bounds', pts }; },
    Browser: { retina: false, mobile: false },
  };
}

/* --------------------------------------------------------------- harness */

function boot({ nodes = [], theme = 'light', restaurants = RESTAURANTS, withL = true, reducedMotion = false, finePointer = true } = {}) {
  const doc = makeDocument();
  doc.documentElement.dataset.theme = theme;
  doc.all = nodes;
  const calls = { map: [], tileLayer: [], marker: [], divIcon: [], polyline: [], layerGroup: [], setView: [], fitBounds: [], flyTo: [], invalidateSize: 0 };
  const rafQueue = [];
  const events = [];

  const sandbox = {};
  sandbox.window = sandbox;
  sandbox.globalThis = sandbox;
  sandbox.document = doc;
  sandbox.console = console;
  sandbox.Math = Math;
  sandbox.Date = Date;
  sandbox.calls = calls;
  sandbox.EAT_DATA = {
    site: { corner: DISTRICT.corner, parking: DISTRICT.parking, landmarks: DISTRICT.landmarks, walking_note: DISTRICT.walking_note, sponsors: DISTRICT.sponsors },
    restaurants,
    categories: [],
  };
  if (withL) sandbox.L = makeL(calls);

  const winListeners = Object.create(null);
  sandbox.addEventListener = (type, fn) => { (winListeners[type] = winListeners[type] || []).push(fn); };
  sandbox.removeEventListener = (type, fn) => { winListeners[type] = (winListeners[type] || []).filter((f) => f !== fn); };
  sandbox.dispatchEvent = (ev) => { events.push(ev.type); (winListeners[ev.type] || []).slice().forEach((fn) => fn(ev)); return true; };
  sandbox.CustomEvent = class CustomEvent {
    constructor(type, init) { this.type = type; this.detail = init && init.detail; }
  };
  sandbox.requestAnimationFrame = (fn) => { rafQueue.push(fn); return rafQueue.length; };
  sandbox.matchMedia = (q) => ({
    media: q,
    matches: q.indexOf('reduced-motion') !== -1 ? reducedMotion : (q.indexOf('pointer: fine') !== -1 ? finePointer : false),
    addEventListener() {}, removeEventListener() {}, addListener() {}, removeListener() {},
  });
  sandbox.getComputedStyle = () => ({ getPropertyValue: (k) => (k === '--accent' ? (doc.documentElement.dataset.theme === 'dark' ? ' #E8683F ' : ' #C4472A ') : '') });

  vm.createContext(sandbox);
  vm.runInContext(HOURS, sandbox, { filename: 'hours.js' });
  vm.runInContext(MAP, sandbox, { filename: 'map.js' });

  return {
    sandbox, doc, calls, events, winListeners,
    L: sandbox.L,
    api: sandbox.EatMap,
    flushRaf() { while (rafQueue.length) rafQueue.shift()(); },
    fireWindow(type, detail) { sandbox.dispatchEvent(new sandbox.CustomEvent(type, { detail })); },
    setL(next) { sandbox.L = next; },
  };
}

const restaurantMarkers = (c) => c.marker.filter((m) => /class="eat-pin"/.test(m.icon.html || ''));
const carMarkers = (c) => c.marker.filter((m) => (m.icon.html || '').indexOf(CAR_PATH) !== -1);
const pinMarkers = (c) => c.marker.filter((m) => (m.icon.html || '').indexOf(PIN_PATH) !== -1);
const walkMarkers = (c) => c.marker.filter((m) => m.icon.className === 'walk-label-wrap');

