group('init on a home-page map');
{
  const mapEl = makeEl({ map: '', zoom: '17' }, 'div');
  const parkBtn = makeEl({ layer: 'parking' }, 'button');
  const landBtn = makeEl({ layer: 'landmarks' }, 'button');
