  test('dragging is enabled for touch', () => assert.equal(c.map[0].dragging.enabled(), true));
  test('adds 4 restaurant markers', () => assert.equal(restaurantMarkers(c).length, 4));
  test('restaurant pins carry the data initials', () => {
    const letters = restaurantMarkers(c).map((m) => m.icon.html.match(/>([^<]*)</)[1]);
    assert.deepEqual(letters.sort(), ['H', 'I', 'K', 'R']);
  });
  test('restaurant divIcon uses the contract size and anchor', () => {
    const icon = restaurantMarkers(c)[0].icon;
    assert.equal(icon.className, 'eat-pin-wrap');
    assert.deepEqual(icon.iconSize, [38, 38]);
