  test('adds 5 parking markers with the Phosphor car-simple path', () => assert.equal(carMarkers(c).length, 5));
  test('parking pins use .eat-pin.alt', () => assert.match(carMarkers(c)[0].icon.html, /class="eat-pin alt"/));
  test('adds 8 landmark markers with the Phosphor map-pin path', () => assert.equal(pinMarkers(c).length, 8));
  test('draws one polyline with 5 points', () => {
    assert.equal(c.polyline.length, 1);
    assert.equal(c.polyline[0].pts.length, 5);
  });
  test('loop runs rancho, harvest, kaias, incontro, rancho', () => {
    const by = Object.fromEntries(RESTAURANTS.map((r) => [r.slug, [r.lat, r.lng]]));
    assert.deepEqual(c.polyline[0].pts, [by['rancho-cantina'], by.harvest, by.kaias, by.incontro, by['rancho-cantina']]);
  });
