  test('adds 4 walking labels', () => assert.equal(walkMarkers(c).length, 4));
  test('every corner hop reads 1 min', () => {
    walkMarkers(c).forEach((m) => assert.match(m.icon.html, /<span class="walk-label">1 min<\/span>/));
  });
  test('walk labels sit at the segment midpoints', () => {
    const by = Object.fromEntries(RESTAURANTS.map((r) => [r.slug, r]));
    const ring = ['rancho-cantina', 'harvest', 'kaias', 'incontro', 'rancho-cantina'].map((s) => by[s]);
    walkMarkers(c).forEach((m, i) => {
      assert.ok(Math.abs(m.latlng[0] - (ring[i].lat + ring[i + 1].lat) / 2) < 1e-9);
      assert.ok(Math.abs(m.latlng[1] - (ring[i].lng + ring[i + 1].lng) / 2) < 1e-9);
    });
