    ctx.doc.dispatch('click', { target: landBtn });
    assert.equal(c.map[0].hasLayer(c.layerGroup[2]), true);
    assert.equal(landBtn.getAttribute('aria-pressed'), 'true');
  });
  test('landmark pins get their aria-label once the layer is on', () => {
    assert.ok(pinMarkers(c)[0].getElement().getAttribute('aria-label'));
  });
  test('clicking Landmarks again removes the group', () => {
    ctx.doc.dispatch('click', { target: landBtn });
    assert.equal(c.map[0].hasLayer(c.layerGroup[2]), false);
    assert.equal(landBtn.getAttribute('aria-pressed'), 'false');
