  group('export shape');
  test('window.EatMap is exactly { init, focus, maps }', () => {
    assert.deepEqual(Object.keys(ctx.api).sort(), ['focus', 'init', 'maps']);
    assert.equal(typeof ctx.api.init, 'function');
