group('walking time past the corner');
{
  const far = RESTAURANTS.map((r) => ({ ...r }));
  far[1] = { ...far[1], lat: far[1].lat + 0.01, lng: far[1].lng + 0.004 }; // move Incontro up the street
  const mapEl = makeEl({ map: '', zoom: '17' }, 'div');
  const ctx = boot({ nodes: [mapEl], restaurants: far });
  const labels = walkMarkers(ctx.calls).map((m) => m.icon.html.match(/>([^<]*)</)[1]);

  const feet = (a, b) => {
    const R = 20902231, rad = Math.PI / 180;
    const dLat = (b.lat - a.lat) * rad, dLng = (b.lng - a.lng) * rad;
    const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
    return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
  };
  const by = Object.fromEntries(far.map((r) => [r.slug, r]));
  const ring = ['rancho-cantina', 'harvest', 'kaias', 'incontro', 'rancho-cantina'].map((s) => by[s]);
  const expected = ring.slice(0, 4).map((a, i) => {
    const d = feet(a, ring[i + 1]);
    return d <= 300 ? '1 min' : `${Math.ceil(d / 270)} min`;
  });

  test('long hops round up at 270 feet a minute', () => assert.deepEqual(labels, expected));
  test('the moved stop is no longer a one minute walk', () => {
    assert.ok(labels.some((t) => t !== '1 min'), `labels were ${JSON.stringify(labels)}`);
    labels.forEach((t) => assert.match(t, /^\d+ min$/));
  });
}

