/* Smoke test for src/js/map.js.
   Loads hours.js and map.js into a vm context with a hand-rolled window/document and a recording Leaflet stub,
   then checks the pure logic: marker counts, the loop polyline, walking labels, popups, layers, theme and focus().
   Every expected coordinate is read from data/, never hardcoded, because the data files are still moving. */
import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';

const ROOT = 'C:/Users/Kenneth Rodas/Documents/GitHub/eatdanville';
const HOURS = fs.readFileSync(`${ROOT}/src/js/hours.js`, 'utf8');
const MAP = fs.readFileSync(`${ROOT}/src/js/map.js`, 'utf8');
const RESTAURANTS = JSON.parse(fs.readFileSync(`${ROOT}/data/restaurants.json`, 'utf8'));
const DISTRICT = JSON.parse(fs.readFileSync(`${ROOT}/data/district.json`, 'utf8'));

const BY_SLUG = Object.fromEntries(RESTAURANTS.map((r) => [r.slug, r]));
const RING_SLUGS = ['rancho-cantina', 'harvest', 'kaias', 'incontro', 'rancho-cantina'];
const CAR_PATH = 'M240,104H229.2L201.42,41.5';
const PIN_PATH = 'M128,64a40,40,0,1,0,40,40A40,40,0,0,0,128,64Z';

// Independent great-circle distance, so the module's walking math is checked against something, not itself.
function feetBetween(a, b) {
  const R = 20902231, rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad, dLng = (b.lng - a.lng) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
}
function expectedLabels(bySlug) {
  const ring = RING_SLUGS.map((s) => bySlug[s]);
  return ring.slice(0, 4).map((a, i) => {
    const d = feetBetween(a, ring[i + 1]);
    return d <= 300 ? '1 min' : `${Math.ceil(d / 270)} min`;
  });
}

let passed = 0;
const failures = [];
function test(name, fn) {
  try { fn(); passed++; console.log(`  ok   ${name}`); }
  catch (err) { failures.push({ name, err }); console.log(`  FAIL ${name}\n       ${err && err.message}`); }
}
function group(name) { console.log(`\n${name}`); }
// Values built inside the vm carry that realm's prototypes, so compare by shape.
function same(actual, expected, msg) {
  assert.deepEqual(JSON.parse(JSON.stringify(actual)), JSON.parse(JSON.stringify(expected)), msg);
}

/* ---------------------------------------------------------------- fake DOM */

function selMatch(node, sel) {
  const attr = sel.match(/^\[data-([a-z-]+)(?:="([^"]*)")?\]$/);
  if (attr) {
    const key = attr[1].replace(/-([a-z])/g, (m, c) => c.toUpperCase());
    if (!node.dataset || !(key in node.dataset)) return false;
    return attr[2] === undefined ? true : node.dataset[key] === attr[2];
  }
  if (sel.startsWith('.')) return node.classList.contains(sel.slice(1));
  return node.tagName === sel;
}

function makeEl(dataset = {}, tag = 'div', classes = []) {
  const listeners = Object.create(null);
  const owned = new Set(classes);
  const node = {
    tagName: tag,
    dataset,
    children: [],
    parent: null,
    attrs: Object.create(null),
    listeners,
    classList: {
      add: (c) => owned.add(c),
      remove: (c) => owned.delete(c),
      contains: (c) => owned.has(c),
      toggle: (c, on) => { const want = on === undefined ? !owned.has(c) : !!on; if (want) owned.add(c); else owned.delete(c); return want; },
    },
    setAttribute(k, v) { node.attrs[k] = String(v); },
    getAttribute(k) { return k in node.attrs ? node.attrs[k] : null; },
    addEventListener(type, fn) { (listeners[type] = listeners[type] || []).push(fn); },
    removeEventListener(type, fn) { listeners[type] = (listeners[type] || []).filter((f) => f !== fn); },
    dispatch(type, ev) { (listeners[type] || []).slice().forEach((fn) => fn(Object.assign({ type, target: node }, ev || {}))); },
    appendChild(child) { child.parent = node; node.children.push(child); return child; },
    contains(other) { let n = other; while (n) { if (n === node) return true; n = n.parent; } return false; },
    querySelector(sel) { return node.descendants().find((c) => selMatch(c, sel)) || null; },
    querySelectorAll(sel) { return node.descendants().filter((c) => selMatch(c, sel)); },
    closest(sel) { let n = node; while (n) { if (selMatch(n, sel)) return n; n = n.parent; } return null; },
    descendants() { return node.children.flatMap((c) => [c, ...c.descendants()]); },
  };
  return node;
}

// Turns a divIcon html string into a tiny element tree so classList and querySelector work on it.
function nodeFromHtml(html) {
  const host = makeEl({}, 'div');
  const re = /<(div|span)\s+class="([^"]*)"/g;
  let m;
  while ((m = re.exec(html))) host.appendChild(makeEl({}, m[1], m[2].split(/\s+/).filter(Boolean)));
  host.html = html;
  return host;
}

function makeDocument() {
  const listeners = Object.create(null);
  const doc = {
    readyState: 'complete',
    documentElement: makeEl({ theme: 'light' }, 'html'),
    activeElement: null,
    all: [],
    listeners,
    querySelectorAll(sel) { return doc.all.filter((n) => selMatch(n, sel)); },
    querySelector(sel) { return doc.querySelectorAll(sel)[0] || null; },
    addEventListener(type, fn) { (listeners[type] = listeners[type] || []).push(fn); },
    removeEventListener(type, fn) { listeners[type] = (listeners[type] || []).filter((f) => f !== fn); },
    dispatch(type, ev) { (listeners[type] || []).slice().forEach((fn) => fn(Object.assign({ type }, ev || {}))); },
  };
  return doc;
}

/* ------------------------------------------------------------ leaflet stub */

function emptyCalls() {
  return { map: [], tileLayer: [], marker: [], divIcon: [], polyline: [], layerGroup: [], setView: [], fitBounds: [], flyTo: [], invalidateSize: 0 };
}

function makeL(calls) {
  function makeGroup() {
    const g = {
      kind: 'layerGroup',
      layers: [],
      map: null,
      addLayer(l) { g.layers.push(l); if (g.map && l.setOnMap) l.setOnMap(true); return g; },
      removeLayer(l) { g.layers = g.layers.filter((x) => x !== l); return g; },
      addTo(map) { map.addLayer(g); return g; },
      getLayers() { return g.layers; },
    };
    return g;
  }

  function makeMarker(latlng, opts) {
    const icon = (opts && opts.icon) || {};
    const el = nodeFromHtml(icon.html || '');
    const m = {
      kind: 'marker',
      latlng,
      options: opts || {},
      icon,
      popup: null,
      popupOpened: 0,
      onMap: false,
      handlers: Object.create(null),
      addTo(target) { if (target && target.addLayer) target.addLayer(m); return m; },
      setOnMap(on) { m.onMap = !!on; },
      bindPopup(html, o) { m.popup = html; m.popupOptions = o; return m; },
      openPopup() { m.popupOpened++; (m.handlers.popupopen || []).forEach((fn) => fn({ type: 'popupopen' })); return m; },
      getLatLng() { return latlng; },
      getElement() { return m.onMap ? el : null; },
      on(type, fn) { (m.handlers[type] = m.handlers[type] || []).push(fn); return m; },
    };
    calls.marker.push(m);
    return m;
  }

  return {
    map(el, opts) {
      const handlers = Object.create(null);
      const map = {
        kind: 'map',
        el,
        options: opts,
        layers: [],
        zoom: (opts && opts.zoom) || 17,
        addLayer(l) {
          if (map.layers.indexOf(l) === -1) map.layers.push(l);
          l.map = map;
          if (l.layers) l.layers.forEach((x) => x.setOnMap && x.setOnMap(true));
          return map;
        },
        removeLayer(l) {
          map.layers = map.layers.filter((x) => x !== l);
          l.map = null;
          if (l.layers) l.layers.forEach((x) => x.setOnMap && x.setOnMap(false));
          return map;
        },
        hasLayer(l) { return map.layers.indexOf(l) !== -1; },
        setView(ll, z) { calls.setView.push({ ll, z }); map.zoom = z; return map; },
        fitBounds(b, o) { calls.fitBounds.push({ b, o }); return map; },
        flyTo(ll, z, o) { calls.flyTo.push({ ll, z, o }); return map; },
        getZoom() { return map.zoom; },
        invalidateSize() { calls.invalidateSize++; return map; },
        on(type, fn) { (handlers[type] = handlers[type] || []).push(fn); return map; },
        off() { return map; },
        emit(type, ev) { (handlers[type] || []).forEach((fn) => fn(ev || {})); },
        scrollWheelZoom: (() => { let on = false; return { enable() { on = true; }, disable() { on = false; }, enabled() { return on; } }; })(),
        dragging: (() => { let on = false; return { enable() { on = true; }, disable() { on = false; }, enabled() { return on; } }; })(),
      };
      calls.map.push(map);
      return map;
    },
    tileLayer(url, opts) {
      const t = { kind: 'tileLayer', url, options: opts, urls: [url], addTo(map) { map.addLayer(t); return t; }, setUrl(u) { t.url = u; t.urls.push(u); return t; } };
      calls.tileLayer.push(t);
      return t;
    },
    layerGroup() { const g = makeGroup(); calls.layerGroup.push(g); return g; },
    marker: makeMarker,
    divIcon(o) { calls.divIcon.push(o); return Object.assign({ kind: 'divIcon' }, o); },
    polyline(pts, opts) {
      const p = { kind: 'polyline', pts, options: opts, styles: [], addTo(t) { t.addLayer(p); return p; }, setStyle(s) { p.styles.push(s); return p; }, setOnMap() {} };
      calls.polyline.push(p);
      return p;
    },
    latLngBounds(pts) { return { kind: 'bounds', pts }; },
    Browser: { retina: false, mobile: false },
  };
}

/* --------------------------------------------------------------- harness */

function boot({ nodes = [], theme = 'light', restaurants = RESTAURANTS, site, withL = true, reducedMotion = false, finePointer = true } = {}) {
  const doc = makeDocument();
  doc.documentElement.dataset.theme = theme;
  doc.all = nodes;
  const calls = emptyCalls();
  const rafQueue = [];
  const events = [];

  const sandbox = {};
  sandbox.window = sandbox;
  sandbox.globalThis = sandbox;
  sandbox.document = doc;
  sandbox.console = console;
  sandbox.EAT_DATA = {
    site: site || { corner: DISTRICT.corner, parking: DISTRICT.parking, landmarks: DISTRICT.landmarks, walking_note: DISTRICT.walking_note, sponsors: DISTRICT.sponsors },
    restaurants,
    categories: [],
  };
  if (withL) sandbox.L = makeL(calls);

  const winListeners = Object.create(null);
  sandbox.addEventListener = (type, fn) => { (winListeners[type] = winListeners[type] || []).push(fn); };
  sandbox.removeEventListener = (type, fn) => { winListeners[type] = (winListeners[type] || []).filter((f) => f !== fn); };
  sandbox.dispatchEvent = (ev) => { events.push(ev.type); (winListeners[ev.type] || []).slice().forEach((fn) => fn(ev)); return true; };
  sandbox.CustomEvent = class CustomEvent {
    constructor(type, init) { this.type = type; this.detail = init && init.detail; }
  };
  sandbox.requestAnimationFrame = (fn) => { rafQueue.push(fn); return rafQueue.length; };
  sandbox.matchMedia = (q) => ({
    media: q,
    matches: q.indexOf('reduced-motion') !== -1 ? reducedMotion : (q.indexOf('pointer: fine') !== -1 ? finePointer : false),
    addEventListener() {}, removeEventListener() {}, addListener() {}, removeListener() {},
  });
  sandbox.getComputedStyle = () => ({ getPropertyValue: (k) => (k === '--accent' ? (doc.documentElement.dataset.theme === 'dark' ? ' #E8683F ' : ' #C4472A ') : '') });

  vm.createContext(sandbox);
  vm.runInContext(HOURS, sandbox, { filename: 'hours.js' });
  vm.runInContext(MAP, sandbox, { filename: 'map.js' });

  return {
    sandbox, doc, calls, events, winListeners,
    api: sandbox.EatMap,
    flushRaf() { while (rafQueue.length) rafQueue.shift()(); },
    fireWindow(type, detail) { sandbox.dispatchEvent(new sandbox.CustomEvent(type, { detail })); },
    setL(next) { sandbox.L = next; },
  };
}

const restaurantMarkers = (c) => c.marker.filter((m) => /class="eat-pin"/.test(m.icon.html || ''));
const carMarkers = (c) => c.marker.filter((m) => (m.icon.html || '').indexOf(CAR_PATH) !== -1);
const pinMarkers = (c) => c.marker.filter((m) => (m.icon.html || '').indexOf(PIN_PATH) !== -1);
const walkMarkers = (c) => c.marker.filter((m) => m.icon.className === 'walk-label-wrap');
const byInitial = (c, letter) => restaurantMarkers(c).find((m) => new RegExp(`class="eat-pin">${letter}<`).test(m.icon.html));

/* ------------------------------------------------------------------ tests */

console.log(`data under test: ${RESTAURANTS.length} restaurants, ${DISTRICT.parking.length} parking lots, ${DISTRICT.landmarks.length} landmarks`);
console.log(`Kaia's is at ${BY_SLUG.kaias.lat}, ${BY_SLUG.kaias.lng}`);

group('init on a home-page map');
{
  const mapEl = makeEl({ map: '', zoom: '17' }, 'div');
  const parkBtn = makeEl({ layer: 'parking' }, 'button');
  const landBtn = makeEl({ layer: 'landmarks' }, 'button');
  const loopBtn = makeEl({ layer: 'loop' }, 'button');
  const legend = makeEl({ pin: 'kaias' }, 'button');
  const ctx = boot({ nodes: [mapEl, parkBtn, landBtn, loopBtn, legend] });
  const c = ctx.calls;

  test('creates exactly one map per [data-map]', () => assert.equal(c.map.length, 1));
  test('map opens with the wheel handed back to the page', () => assert.equal(c.map[0].options.scrollWheelZoom, false));
  test('dragging is enabled for touch', () => assert.equal(c.map[0].dragging.enabled(), true));
  test('adds 4 restaurant markers', () => assert.equal(restaurantMarkers(c).length, 4));
  test('restaurant pins carry the data initials', () => {
    const letters = restaurantMarkers(c).map((m) => m.icon.html.match(/>([^<]*)</)[1]).sort();
    same(letters, RESTAURANTS.map((r) => r.initial).sort());
  });
  test('restaurant divIcon uses the contract size and anchor', () => {
    const icon = restaurantMarkers(c)[0].icon;
    assert.equal(icon.className, 'eat-pin-wrap');
    same(icon.iconSize, [38, 38]);
    same(icon.iconAnchor, [19, 19]);
  });
  test(`adds ${DISTRICT.parking.length} parking markers with the Phosphor car-simple path`, () => assert.equal(carMarkers(c).length, DISTRICT.parking.length));
  test('parking pins use .eat-pin.alt', () => assert.match(carMarkers(c)[0].icon.html, /class="eat-pin alt"/));
  test(`adds ${DISTRICT.landmarks.length} landmark markers with the Phosphor map-pin path`, () => assert.equal(pinMarkers(c).length, DISTRICT.landmarks.length));
  test('draws one polyline with 5 points', () => {
    assert.equal(c.polyline.length, 1);
    assert.equal(c.polyline[0].pts.length, 5);
  });
  test('loop runs rancho, harvest, kaias, incontro, rancho', () => {
    same(c.polyline[0].pts, RING_SLUGS.map((s) => [BY_SLUG[s].lat, BY_SLUG[s].lng]));
  });
  test('loop takes its color from the --accent token', () => assert.equal(c.polyline[0].options.color, '#C4472A'));
  test('loop is dashed and not clickable', () => {
    assert.ok(c.polyline[0].options.dashArray);
    assert.equal(c.polyline[0].options.interactive, false);
  });
  test('adds 4 walking labels', () => assert.equal(walkMarkers(c).length, 4));
  test('walking labels match an independent distance calculation', () => {
    const labels = walkMarkers(c).map((m) => m.icon.html.match(/>([^<]*)</)[1]);
    same(labels, expectedLabels(BY_SLUG));
  });
  test('every hop across this corner reads 1 min', () => {
    walkMarkers(c).forEach((m) => assert.match(m.icon.html, /<span class="walk-label">1 min<\/span>/));
  });
  test('walk labels sit at the segment midpoints', () => {
    const ring = RING_SLUGS.map((s) => BY_SLUG[s]);
    walkMarkers(c).forEach((m, i) => {
      assert.ok(Math.abs(m.latlng[0] - (ring[i].lat + ring[i + 1].lat) / 2) < 1e-9);
      assert.ok(Math.abs(m.latlng[1] - (ring[i].lng + ring[i + 1].lng) / 2) < 1e-9);
    });
  });
  test('tile layer is CARTO light_all with the retina placeholder', () => {
    assert.equal(c.tileLayer.length, 1);
    assert.equal(c.tileLayer[0].url, 'https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png');
    assert.equal(c.tileLayer[0].options.subdomains, 'abcd');
    assert.equal(c.tileLayer[0].options.maxZoom, 20);
    assert.equal(c.tileLayer[0].options.attribution, '&copy; OpenStreetMap contributors &copy; CARTO');
  });
  test('fits the four with padding 40', () => {
    assert.equal(c.fitBounds.length, 1);
    same(c.fitBounds[0].o.padding, [40, 40]);
    assert.equal(c.fitBounds[0].b.pts.length, 4);
  });
  test('parking and loop are on by default, landmarks are off', () => {
    const g = c.layerGroup;
    assert.equal(c.map[0].hasLayer(g[0]), true, 'restaurants');
    assert.equal(c.map[0].hasLayer(g[1]), true, 'parking');
    assert.equal(c.map[0].hasLayer(g[2]), false, 'landmarks');
    assert.equal(c.map[0].hasLayer(g[3]), true, 'loop');
  });
  test('layer buttons report their state through aria-pressed', () => {
    assert.equal(parkBtn.getAttribute('aria-pressed'), 'true');
    assert.equal(landBtn.getAttribute('aria-pressed'), 'false');
    assert.equal(loopBtn.getAttribute('aria-pressed'), 'true');
  });
  test('eat:map-ready waits a frame so later modules can hear it', () => {
    assert.equal(ctx.events.indexOf('eat:map-ready'), -1);
    ctx.flushRaf();
    assert.ok(ctx.events.includes('eat:map-ready'));
  });
  test('pins expose a name to assistive tech', () => {
    const marker = restaurantMarkers(c)[0];
    assert.equal(marker.getElement().getAttribute('role'), 'button');
    assert.ok(marker.getElement().getAttribute('aria-label'));
  });

  group('popups');
  const kaias = byInitial(c, 'K');
  test('restaurant popup shows the name, the live status line and the links', () => {
    const r = BY_SLUG.kaias;
    const line = ctx.sandbox.EatHours.statusLine(r);
    assert.match(kaias.popup, /^<strong>Kaia&#39;s Island Kitchen &amp; Tiki Bar<\/strong>/);
    assert.ok(kaias.popup.includes(line), `expected the status line ${line}`);
    assert.ok(kaias.popup.includes('<a href="/r/kaias/"'));
    assert.ok(kaias.popup.includes('>Details</a> \u00B7 <a href='));
    assert.ok(kaias.popup.includes('>Reserve</a>'));
  });
  test('the reserve link points at the reservation url from the data', () => {
    const url = BY_SLUG.kaias.reservation_url.replace(/&/g, '&amp;');
    assert.ok(kaias.popup.includes(`href="${url}"`), kaias.popup);
  });
  test('popup links carry the tracking hooks app.js listens for', () => {
    assert.ok(kaias.popup.includes('data-track="map" data-slug="kaias"'));
    assert.ok(kaias.popup.includes('data-track="reserve" data-slug="kaias"'));
  });
  test(`parking popup shows name, address and note`, () => {
    const lot = carMarkers(c)[0];
    const p = DISTRICT.parking[0];
    assert.ok(lot.popup.includes(`<strong>${p.name}</strong>`));
    assert.ok(lot.popup.includes(p.address));
    assert.ok(lot.popup.includes(p.note));
  });
  test('landmark popup shows name and note', () => {
    const lm = pinMarkers(c)[0];
    const l = DISTRICT.landmarks[0];
    assert.ok(lm.popup.includes(`<strong>${l.name.replace(/&/g, '&amp;')}</strong>`));
    assert.ok(lm.popup.includes(l.note.replace(/&/g, '&amp;').replace(/'/g, '&#39;')));
  });
  test('no em-dash or en-dash reaches any rendered string', () => {
    const strings = c.marker.map((m) => `${m.popup || ''}${m.icon.html || ''}`).join('');
    assert.equal(/[\u2014\u2013]/.test(strings), false);
  });

  group('focus');
  test("focus(\"kaias\") flies to Kaia's coordinates", () => {
    ctx.api.focus('kaias');
    assert.equal(c.flyTo.length, 1);
    same(c.flyTo[0].ll, [BY_SLUG.kaias.lat, BY_SLUG.kaias.lng]);
    assert.equal(c.flyTo[0].o.duration, 0.8);
  });
  test('focus opens that pin and marks it active', () => {
    assert.equal(kaias.popupOpened, 1);
    assert.equal(kaias.getElement().querySelector('.eat-pin').classList.contains('is-active'), true);
  });
  test('focus lights up the matching legend row', () => assert.equal(legend.classList.contains('is-active'), true));
  test('focus("parking-village-theatre-lot") resolves the slugified parking id', () => {
    const p = DISTRICT.parking[0];
    const id = 'parking-' + p.name.toLowerCase().replace(/[^a-z0-9]+/g, '-');
    assert.equal(id, 'parking-village-theatre-lot');
    const before = c.flyTo.length;
    assert.ok(ctx.api.focus(id));
    assert.equal(c.flyTo.length, before + 1);
    same(c.flyTo[before].ll, [p.lat, p.lng]);
  });
  test('an unknown id is a no-op, not a throw', () => assert.equal(ctx.api.focus('nope'), null));
  test('focus() with no argument is a no-op', () => assert.equal(ctx.api.focus(), null));

  group('layer toggles');
  test('clicking Landmarks turns the group on and flips aria-pressed', () => {
    ctx.doc.dispatch('click', { target: landBtn });
    assert.equal(c.map[0].hasLayer(c.layerGroup[2]), true);
    assert.equal(landBtn.getAttribute('aria-pressed'), 'true');
  });
  test('landmark pins get their aria-label once the layer is on', () => {
    assert.ok(pinMarkers(c)[0].getElement().getAttribute('aria-label'));
  });
  test('clicking Landmarks again removes the group', () => {
    ctx.doc.dispatch('click', { target: landBtn });
    assert.equal(c.map[0].hasLayer(c.layerGroup[2]), false);
    assert.equal(landBtn.getAttribute('aria-pressed'), 'false');
  });
  test('focusing a hidden parking pin turns its layer back on', () => {
    ctx.doc.dispatch('click', { target: parkBtn });
    assert.equal(c.map[0].hasLayer(c.layerGroup[1]), false);
    const id = 'parking-' + DISTRICT.parking[1].name.toLowerCase().replace(/[^a-z0-9]+/g, '-');
